179:     -- Reutiliza además la reserva y el snapshot documentales del alta publicada.
180:     -- Un PDF pendiente no vuelve a crear el contrato cuando se recupera el envío.
181:     -- El flujo Avance vigente es libre y fotografía sus términos. El catálogo
182:     -- sigue siendo opcional: F4 no lo convierte en un requisito comercial nuevo.
183:     perform pg_catalog.set_config('crm.producto_condicion_id',
184:       coalesce((nullif(v_s.datos->>'producto_condicion_id','')::uuid)::text,''),true);
185:     begin
186:       v_fuente := crm.crear_contrato_con_cuenta_pdf_v2(
187:         v_payload_contrato||jsonb_build_object('clave_idempotencia',v_s.id),
188:         v_s.datos->'cronograma',v_s.datos->'cuenta');
189:     exception when others then
190:       perform pg_catalog.set_config('crm.producto_condicion_id',coalesce(v_config_producto,''),true);
191:       raise;
192:     end;
193:     perform pg_catalog.set_config('crm.producto_condicion_id',coalesce(v_config_producto,''),true);
194:     v_contrato := (v_fuente->>'id')::uuid;
195:     if v_contrato is null then raise exception 'El contrato no devolvió su identificador' using errcode='P0001'; end if;
196:     select producto_condicion_id into v_condicion from public.contratos where id=v_contrato;
197:     v_fuente:=v_fuente||private.metadata_condicion_producto(v_condicion);
198:   else
199:     raise exception 'Empresa sin puerta de inversión disponible' using errcode='P0409';
200:   end if;
201:   v_inversion := private.inversion_vincular_fuente(v_persona,v_contrato,v_cierre,v_uid,false);
202:   if v_ajuste then
203:     insert into crm.inversion_ajustes_mes_cerrado(inversion_id,periodo_origen,fecha_imputacion,creado_por)
204:     values(v_inversion,v_periodo,v_imputacion,v_uid);
205:   end if;
206:   insert into crm.inversion_eventos(inversion_id,tipo,creado_por) values(v_inversion,'registro',v_uid);
207:   v_res := jsonb_build_object('ok',true,'solicitud_id',v_s.id,'inversion_id',v_inversion,
208:     'inversionista_id',v_persona,'lead_id',v_ctx->>'lead_id','empresa',v_e.clave,'fuente',v_fuente);
209:   update crm.inversion_solicitudes set estado='confirmada',inversion_id=v_inversion,
210:     resultado=v_res,confirmado_por=v_uid,actualizado_en=statement_timestamp() where id=v_s.id;
211:   return v_res;
212: end;
213: $$;
