FUNCTION crm.crear_contrato_con_cuenta_pdf_v2(jsonb,jsonb,jsonb)
1: 
2: declare
3:   v_actor_id uuid := (select auth.uid());
4:   v_contrato jsonb := p_contrato;
5:   v_resultado jsonb;
6:   v_contrato_id uuid;
7:   v_pdf jsonb;
8:   v_clave_texto text := nullif(btrim(coalesce(p_contrato->>'clave_idempotencia', '')), '');
9:   v_clave uuid;
10:   v_huella text;
11:   v_huella_previa text;
12: begin
13:   perform private.inversiones_escritura_bajo_candado(); -- F4: bandera antes de persona/cuenta/PDF
14:   if v_actor_id is null then
15:     raise insufficient_privilege using message = 'Sesión no válida';
16:   end if;
17: 
18:   -- IDEMPOTENCIA DEL ALTA (05/09/2026). El front manda una clave (uuid) por intento de
19:   -- formulario, la MISMA en cada reintento. Si este actor ya registró un alta con esa
20:   -- clave, se devuelve el MISMO contrato en vez de crear otro. Viaja DENTRO de
110:     p_cronograma,
111:     p_cuenta
112:   );
113:   begin
114:     v_contrato_id := (v_resultado->>'id')::uuid;
115:   exception when invalid_text_representation then
116:     raise exception 'El alta no devolvió un contrato válido'
117:       using errcode = 'P0001';
118:   end;
119:   if v_contrato_id is null then
120:     raise exception 'El alta no devolvió un contrato válido'
121:       using errcode = 'P0001';
122:   end if;
123: 
124:   v_pdf := private.crear_job_contrato_pdf_base(v_contrato_id, v_actor_id);
125:   v_resultado := v_resultado || jsonb_build_object('pdf', v_pdf);
126:   if v_clave is not null then
127:     -- Misma transacción que el alta: o quedan los dos, o ninguno.
128:     insert into private.contrato_altas_idempotentes (actor_id, clave, contrato_id, huella, respuesta)
129:     values (v_actor_id, v_clave, v_contrato_id, v_huella, v_resultado);
130:   end if;
131:   return v_resultado;
132: end;

FUNCTION crm.fusionar_inversionistas_fn(uuid,uuid,text,text)
1: 
2: declare
3:   v_uid uuid;
4:   v_p crm.inversionistas%rowtype; v_c crm.inversionistas%rowtype; v_row crm.inversionistas%rowtype;
5:   v_lead crm.leads%rowtype; v_leads uuid[]; v_docs text[]; v_docs2 text[]; v_bloq text[]; v_foto jsonb; v_ahora timestamptz;
6:   v_veto boolean; v_tramo_p crm.inversionista_responsables%rowtype; v_tramo_c crm.inversionista_responsables%rowtype;
7:   v_t crm.inversion_titulares%rowtype; v_t2 crm.inversion_titulares%rowtype; v_fusion_id uuid; v_impacto jsonb;
8:   v_n_ident integer := 0; v_n_cierres integer := 0; v_n_inv integer := 0; v_n_tit integer := 0;
9:   v_perfiles_fusion uuid[] := '{}';        -- F2.b [D-18] (N6): perfiles cliente de las dos personas (tareas de cliente)
10:   v_n_tareas_cliente integer := 0;         -- F2.b [D-18] (N6)
11:   v_n_tit_dup integer := 0; v_n_res integer := 0; v_n_pred integer := 0; v_n_tareas integer := 0; v_n_puente integer := 0;
12: begin
13:   if not private.resolver_en_puertas_bajo_candado() then
14:     raise exception 'Identidad unificada apagada' using errcode = 'P0409';
15:   end if;
16:   if not private.es_gerencia_crm_activa() then
17:     raise exception 'Solo Gerencia fusiona identidades' using errcode = '42501';
18:   end if;
19:   v_uid := (select auth.uid());
20:   if p_perdedora is null or p_canonica is null or p_perdedora = p_canonica then
21:     raise exception 'Indica dos identidades distintas' using errcode = '22023';
22:   end if;
23:   if p_hash is null or p_hash !~ '^[a-f0-9]{64}$' then
24:     raise exception 'Falta la huella de la previsualización (p_hash)' using errcode = '22023';
25:   end if;
26: 
27:   -- 1. jerarquía compartida [E3-2] y Gerencia REVALIDADA bajo ella -> 2. documentos vigentes de ambas (sin lock, ordenados)
28:   perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0));
29:   if not private.es_gerencia_crm_activa() then
30:     raise exception 'Solo Gerencia fusiona identidades (membresía revalidada)' using errcode = '42501';
31:   end if;
32:   v_docs := private.identidad_bloquear_documentos_de(array[p_perdedora, p_canonica]);
33:   perform private.motivo_sin_documento(p_motivo, (select pg_catalog.array_agg(d.documento_normalizado) from crm.inversionista_identificadores d where d.inversionista_id in (p_perdedora, p_canonica)));
34:   -- 3. identidades FOR UPDATE por id ascendente (P, C y las predecesoras de P: el aplanado no espera después de las reservas [E3-12])
35:   for v_row in select * from crm.inversionistas where id in (p_perdedora, p_canonica) order by id for update loop
36:     if v_row.id = p_perdedora then v_p := v_row; else v_c := v_row; end if;
37:   end loop;
38:   if v_p.id is null or v_c.id is null then
39:     raise exception 'Alguna de las identidades no existe' using errcode = 'P0002';
40:   end if;
41:   perform 1 from crm.inversionistas i where i.inversionista_canonico_id = p_perdedora and i.id not in (p_perdedora, p_canonica) order by i.id for update;
42:   select pg_catalog.array_agg(k order by k) into v_docs2
43:   from (select distinct d.tipo_documento || ':' || d.documento_normalizado as k
44:         from crm.inversionista_identificadores d where d.inversionista_id in (p_perdedora, p_canonica) and d.estado = 'vigente') s;
45:   if coalesce(v_docs2, '{}') is distinct from v_docs then
46:     raise exception 'Los documentos de la persona cambiaron mientras se esperaba; vuelve a previsualizar' using errcode = '40001';
47:   end if;
48:   -- 4. perfiles FOR SHARE (directos y de los leads [Codex B1]) -> 5. cierres -> 6. inversiones/titulares -> 7. tramos -> 8. tareas -> 9. leads (NOWAIT) -> 10. reservas -> 11. claims
49:   v_leads := coalesce((select pg_catalog.array_agg(x order by x) from private.leads_de_identidades(array[p_perdedora, p_canonica]) x), '{}');
50:   perform 1 from public.perfiles p
51:    where p.id in (v_p.perfil_id, v_c.perfil_id) or p.id in (select l.perfil_id from crm.leads l where l.id = any(v_leads))
52:    order by p.id for share;
53:   perform 1 from crm.cierres_externos ce
54:    where ce.inversionista_id in (p_perdedora, p_canonica) or ce.lead_id = any(v_leads)
55:    order by ce.id for update;
56:   perform 1 from crm.inversiones i where i.inversionista_id in (p_perdedora, p_canonica) order by i.id for update;
57:   perform 1 from crm.inversion_titulares t
58:    where t.inversionista_id in (p_perdedora, p_canonica)
59:       or t.inversion_id in (select i.id from crm.inversiones i where i.inversionista_id in (p_perdedora, p_canonica))
60:    order by t.id for update;
155:   update crm.cierres_externos ce set inversionista_id = p_canonica
156:    where ce.inversionista_id = p_perdedora
157:       or (v_lead.id is not null and v_lead.inversionista_id = p_perdedora and ce.lead_id = v_lead.id and ce.inversionista_id is null);
158:   get diagnostics v_n_cierres = row_count;
159:   update crm.inversiones set inversionista_id = p_canonica where inversionista_id = p_perdedora;
160:   get diagnostics v_n_inv = row_count;
161:   for v_t in select * from crm.inversion_titulares where inversionista_id = p_perdedora order by id loop
162:     v_t2 := null;
163:     select * into v_t2 from crm.inversion_titulares where inversion_id = v_t.inversion_id and inversionista_id = p_canonica;
164:     if v_t2.id is not null then
165:       delete from crm.inversion_titulares where id = v_t.id;
166:       if v_t.rol = 'principal' and v_t2.rol <> 'principal' then
167:         update crm.inversion_titulares set rol = 'principal' where id = v_t2.id;
168:       end if;
169:       v_n_tit_dup := v_n_tit_dup + 1;
170:     else
171:       update crm.inversion_titulares set inversionista_id = p_canonica where id = v_t.id;
172:       v_n_tit := v_n_tit + 1;
173:     end if;
174:   end loop;
175:   update crm.conversion_reservas set inversionista_id = p_canonica where inversionista_id = p_perdedora;
176:   get diagnostics v_n_res = row_count;
177:   v_impacto := pg_catalog.jsonb_build_object('lead_id', v_lead.id, 'lead_reapuntado', v_lead.id is not null and v_lead.inversionista_id = p_perdedora,
178:     'puente', v_n_puente, 'identificadores_reemitidos', v_n_ident, 'tramo_cerrado', v_tramo_p.id, 'tramo_heredado', v_tramo_c.id is null and v_tramo_p.id is not null,
179:     'perfil_heredado', v_c.perfil_id is null and v_p.perfil_id is not null, 'veto', v_veto, 'tareas_canceladas', v_n_tareas, 'tareas_cliente_canceladas', v_n_tareas_cliente,
180:     'cierres', v_n_cierres, 'inversiones', v_n_inv, 'titulares', v_n_tit, 'titulares_duplicados_eliminados', v_n_tit_dup,
181:     'reservas', v_n_res, 'predecesoras_aplanadas', v_n_pred, 'hash', p_hash);

FUNCTION private.proteger_titulares_documentales()
1: 
2: declare
3:   v_anterior uuid := case when tg_op in ('UPDATE', 'DELETE') then old.contrato_id end;
4:   v_nuevo uuid := case when tg_op in ('INSERT', 'UPDATE') then new.contrato_id end;
5: begin
6:   if tg_op = 'DELETE'
7:      and current_setting('crm.contrato_pdf_eliminacion_autorizada', true)
8:            = old.contrato_id::text then
9:     return old;
10:   end if;
11:   if tg_op = 'UPDATE' and new is not distinct from old then return new; end if;
12: 
13:   perform private.bloquear_contratos_hijo_documental(v_anterior, v_nuevo);
14:   if (
15:     v_anterior is not null
16:     and (
17:       private.contrato_en_eliminacion(v_anterior)
18:       or private.contrato_documental_congelado(v_anterior)
19:     )
20:     and not private.mutacion_documental_autorizada(v_anterior)
21:   ) or (
22:     v_nuevo is not null
23:     and (
24:       private.contrato_en_eliminacion(v_nuevo)
25:       or private.contrato_documental_congelado(v_nuevo)
26:     )
27:     and not private.mutacion_documental_autorizada(v_nuevo)
28:   ) then
29:     raise exception 'Los titulares están congelados por su PDF legal'
30:       using errcode = '55000';
31:   end if;
32: 
33:   if tg_op = 'DELETE' then return old; end if;
34:   return new;
35: end;
